const items = $input.all();
const results = [];
for (const item of items) {
  const subject = item.json.subject || '';
  const body = item.json.snippet || item.json.textPlain || '';
  const from = item.json.from || '';
  const date = item.json.date || new Date().toISOString();

  // Parse task priority from subject
  let priority = 'normal';
  if (subject.toLowerCase().includes('urgent') || subject.toLowerCase().includes('asap')) {
    priority = 'high';
  } else if (subject.toLowerCase().includes('fyi') || subject.toLowerCase().includes('low')) {
    priority = 'low';
  }

  // Extract action items from body
  const actionMatch = body.match(/action:?\s*(.+)/i);
  const action = actionMatch ? actionMatch[1].trim() : subject;

  results.push({
    json: {
      taskTitle: action,
      description: body.substring(0, 500),
      priority: priority,
      source: from,
      emailSubject: subject,
      createdAt: date,
      status: 'open'
    }
  });
}
return results;
